// 520×520 transparent PNG, downscaled from
// packages/worker/public/images/kody-lantern.webp — the pre-composed hero
// (Kody plus the floating notes, packages, and tool tokens) that the landing
// page builds from separate parallax layers. Flattened here because a static
// card has nothing to parallax, and one asset beats stitching ten.
const KODY_HERO_PNG_BASE64 =
	''

export function getKodyHeroDataUri(): string {
	return `data:image/png;base64,${KODY_HERO_PNG_BASE64}`
}
